import { Clipboard } from '@angular/cdk/clipboard';
import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { MAT_DIALOG_DATA, MatDialogModule } from '@angular/material/dialog';
import { MatIconModule } from '@angular/material/icon';

export interface GeneratedPasswordDialogData {
  /** What happened, e.g. "Usuario creado". */
  title: string;
  userName: string;
  email: string;
  password: string;
}

/**
 * Shows a password generated by the backend. It is the only chance to see it, so the dialog does not
 * close by clicking outside or pressing Escape (see `disableClose` where it is opened).
 */
@Component({
  selector: 'app-generated-password-dialog',
  imports: [MatButtonModule, MatDialogModule, MatIconModule],
  template: `
    <h2 mat-dialog-title>{{ data.title }}</h2>
    <mat-dialog-content>
      <p>
        Contraseña de <strong>{{ data.userName }}</strong> ({{ data.email }}):
      </p>
      <div class="password">
        <code>{{ data.password }}</code>
        <button
          mat-icon-button
          type="button"
          [attr.aria-label]="copied() ? 'Contraseña copiada' : 'Copiar contraseña'"
          (click)="copy()"
        >
          <mat-icon aria-hidden="true">{{ copied() ? 'check' : 'content_copy' }}</mat-icon>
        </button>
      </div>
      <p class="cdk-visually-hidden" role="status">{{ copied() ? 'Contraseña copiada' : '' }}</p>
      <p class="warning">
        <mat-icon aria-hidden="true">warning</mat-icon>
        Cópiala ahora y hazla llegar al usuario: no se podrá volver a ver. Si se pierde, habrá que
        restablecerla.
      </p>
    </mat-dialog-content>
    <mat-dialog-actions align="end">
      <button mat-flat-button type="button" mat-dialog-close cdkFocusInitial>Hecho</button>
    </mat-dialog-actions>
  `,
  styles: `
    .password {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 8px 8px 8px 16px;
      border-radius: 12px;
      background: var(--mat-sys-surface-container-highest);
    }

    code {
      flex: 1;
      font:
        500 1.25rem / 1.5 ui-monospace,
        monospace;
      letter-spacing: 0.05em;
      color: var(--mat-sys-on-surface);
      overflow-wrap: anywhere;
    }

    .warning {
      display: flex;
      gap: 8px;
      margin-top: 16px;
      color: var(--mat-sys-on-surface-variant);

      mat-icon {
        flex: none;
        color: var(--mat-sys-error);
      }
    }
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class GeneratedPasswordDialog {
  private readonly clipboard = inject(Clipboard);
  protected readonly data = inject<GeneratedPasswordDialogData>(MAT_DIALOG_DATA);
  protected readonly copied = signal(false);

  protected copy(): void {
    this.copied.set(this.clipboard.copy(this.data.password));
  }
}
